{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Isradipine, a lipophilic dihydropyridine with high assay transfer, has a mean systemic availability of 16.5% in healthy volunteers after oral administration, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Pentazocine has an absolute oral bioavailability of 18% in healthy subjects, below the 20% threshold, providing affirmative low-F evidence.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Nifedipine has an oral bioavailability of about 45% in humans, above the threshold, showing that some lipophilic small molecules can exceed 20% despite first-pass metabolism.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "A pyrazolopyrimidinone analogue has 34% oral bioavailability in healthy volunteers, above the threshold, but is a much smaller, more soluble drug-like molecule than the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted low: the query is a very large, highly lipophilic polyprenyl ubiquinone (CoQ10-like) with negligible aqueous solubility. The most transferable affirmative low-F human measurements (isradipine 16.5%, pentazocine 18%) support F<20%, while the high-F analogues are smaller, more drug-like molecules and do not overcome the expected absorption barrier. Confidence is low because no direct CoQ10 or long-chain polyprenyl quinone bioavailability data are present.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for CoQ10 or a long-chain polyprenyl quinone.",
    "All retrieved analogues are small drug-like molecules; none capture the query's extreme molecular weight, logP, and insolubility.",
    "Low-F analogues are primarily first-pass/metabolism-limited, whereas the query is expected to be absorption/solubility-limited, making mechanism transfer uncertain.",
    "Formulation dependence of the query's bioavailability is not addressed by the evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

